import jadx.api.*;import java.io.*;import java.util.*;
public class Inspect {public static void main(String[] a)throws Exception{JadxArgs x=new JadxArgs();x.setInputFiles(List.of(new File(a[0])));x.setSkipSources(true);try(JadxDecompiler d=new JadxDecompiler(x)){d.load();System.out.println("CLASSES="+d.getClasses().size());for(ResourceFile r:d.getResources())if(r.getOriginalName().equals("AndroidManifest.xml"))System.out.println(r.loadContent().getText());for(JavaClass c:d.getClasses()){String n=c.getFullName();if(n.toLowerCase().matches(".*(runna|runbuddy|garmin|amplify|cognito|mapbox|revenuecat|sentry|mixpanel|statsig).*"))System.out.println("CLASS "+n);}}}}
